add_action( 'woocommerce_new_order', 'perfectpixel_auto_cancel_schedule', 20 );
add_action( 'perfectpixel_auto_cancel_order', 'perfectpixel_auto_cancel_run' );

function perfectpixel_auto_cancel_schedule( $order_id ) {
	if ( function_exists( 'as_schedule_single_action' ) ) {
		$delay = max( 1, (float) '{{auto_cancel_hours}}' ) * HOUR_IN_SECONDS;
		as_schedule_single_action( time() + (int) $delay, 'perfectpixel_auto_cancel_order', array( 'order_id' => (int) $order_id ), 'perfectpixel' );
	}
}

function perfectpixel_auto_cancel_run( $order_id ) {
	$order    = wc_get_order( $order_id );
	$statuses = array_filter( array_map( 'sanitize_key', explode( ',', '{{auto_cancel_statuses}}' ) ) );
	if ( $order && $statuses && $order->has_status( $statuses ) && ! $order->is_paid() ) {
		$order->update_status( 'cancelled', 'Ακυρώθηκε αυτόματα: δεν πληρώθηκε εγκαίρως.' );
	}
}
